Let $\mathcal{X}$ be the link of an isolated singularity in an 8-dimensional toric variety. Let $(M , \partial M)$ be the $\mathbb{Q}$-manifold obtained by cutting out all 1-dimensional singularities of $\mathcal{X}$ and $i: \partial M \xhookrightarrow[]{ \;\;\;\; } M  $ be the inclusion map. Then, the Betti numbers of $\mathcal{X}$ are
 	\begin{align*}
 	b^{\mathcal{X}}_{7}=1, \;	b^{\mathcal{X}}_{6}=0, \;	&b^{\mathcal{X}}_{5}=f_{1}-4,\;	b^{\mathcal{X}}_{4}=3f_{1}-f_{2}-6, \;
 	b^{\mathcal{X}}_{3}=3f_{1}-f_{2}-6-b_{2}, \\	&b^{\mathcal{X}}_{2}=f_{1}-4-b_{2}, \;	b^{\mathcal{X}}_{1}=0, \; b^{\mathcal{X}}_{0}=1,
 \end{align*}
 	where 	$b_{2} = \operatorname{rk}(\operatorname{ker}(H_{3}(\partial M) \xrightarrow{ \; \;  i_{\ast}  \; \; } H_{3} (M)  ))$, and $f_{1}$ and $f_{2}$ are the numbers of the 2-dimensional and 1-dimensional faces of the underlying polytope of $\mathcal{X}$, respectively.

Let $\mathcal{X}$ be the link of an isolated singularity in an 8-dimensional toric variety. Let $I^{\bar{n}}\mathcal{X}$ be the generalized intersection space associated with $\mathcal{X}$ with respect to middle perversity $\bar{n}$, as defined in Definition \ref{IXgen}. Then, the Betti numbers of $I^{\bar{n}}\mathcal{X}$ are given by
 \begin{align*}
 	b_{7}^{I^{\bar{n}}\mathcal{X}}&=0,\; 
 	b_{6}^{I^{\bar{n}}\mathcal{X}}=m-1, \;
 	b_{5}^{I^{\bar{n}}\mathcal{X}}=f_{2}-4-b_{2}, \;
 	b_{4}^{I^{\bar{n}}\mathcal{X}}=3f_{1}-f_{2}-6-b_{2}, \\
 	b_{3}^{I^{\bar{n}}\mathcal{X}}&=3f_{1}-f_{2}-6-b_{2},  \;
 	b_{2}^{I^{\bar{n}}\mathcal{X}}=f_{2}-4-b_{2}, \;
 	b_{1}^{I^{\bar{n}}\mathcal{X}}=m-1, \;
 	b_{0}^{I^{\bar{n}}\mathcal{X}}=1, 
 \end{align*}
 where $f_{1}$ and $f_{2}$ are the numbers of 2-dimensional and 1-dimensional faces of the underlying 3-dimensional polytope of $\mathcal{X}$, $\mathcal{P}$. The parameter $m$ denotes the number of rationally singular components of $\mathcal{X}_{1}$, and $b_{2}$ is defined in Equation (\ref{bp2}), or equivalently, in the above theorem.

\label{Bijection}
	The faces in $\mathcal{P}(\Sigma)$ are in one-to-one correspondence 
	(in complementary dimension) with the cones in $\Sigma$. This defines a 
	bijection $\delta: \mathcal{P} \longrightarrow \Sigma$ and we denote the dual 
	cone to $\tau \in \mathcal{P}$ by $\delta(\tau)\in \Sigma$. In particular $\Sigma$ can be reconstructed from $\mathcal{
		P}$. From that perspective we shall also write $\Sigma= \Sigma_{\mathcal{P}}$.

{} 
	The 0-dimensional faces of $\mathcal{P}$ are called \textbf{vertices}. The 1-dimensional faces are called \textbf{edges} and \textbf{facets} are faces with co-dimension 1. The set
	$\mathcal{P}^{i} = \{ F: \: F \: \textit{is a face of} \: \mathcal{P} , \: \dim(F) \leq i \}$ is the i-skeleton of $\mathcal{P}$.

\label{pseudomanifolds}
	We define a \textbf{topologically stratified space} inductively on dimension. A 0-dimensional topologically stratified space $X$ is a countable set with the discrete topology. For $m > 0$ an \textbf{$m$-dimensional topologically stratified space} is a para-compact Hausdorff topological space $X$ equipped with a filtration
	\begin{align*}
		X=X_{m} \supseteq X_{m-1} \supseteq \dots \supseteq X_{1} \supseteq X_{0} \supseteq X_{-1}= \emptyset
	\end{align*}
	by closed subsets $X_{j}$ such that if $x \in X_{j}-X_{j-1}$ there exists a neighborhood $\mathcal{N}_{x}$ of $x$ in $X$, a compact $(m-j-1)$-dimensional topologically stratified space $\mathcal{L}$ with filtration
	\begin{align*}
		\mathcal{L}=\mathcal{L}_{m-j-1} \supseteq \dots \supseteq \mathcal{L}_{1} \supseteq  \mathcal{L}_{0} \supseteq \mathcal{L}_{-1} = \emptyset,
	\end{align*}  
	and a homeomorphism $\phi : \mathcal{N}_{x} \longrightarrow \mathbb{R}^{j} \times \mathcal{C}(\mathcal{L}),$
	where $\mathcal{C}(\mathcal{L})$ is the open cone on $\mathcal{L}$, such that $\phi$ takes $\mathcal{N}_{x} \cap X_{j+i+1}$ homeomorphically onto
	\begin{align*}
		\mathbb{R}^{j} \times \mathcal{C}(\mathcal{L}_{i}) \subseteq \mathbb{R}^{j} \times \mathcal{C}(\mathcal{L})
	\end{align*}
	for $m-j-1 \geq i \geq 0$, and $\phi$ takes $\mathcal{N}_{x} \cap X_{j}$ homeomorphically onto
	\begin{align*}
		\mathbb{R}^{j} \times \{ \text{vertex of }\; \mathcal{C}(\mathcal{L}) \}.
	\end{align*}

\label{PSMFD}
	An \textbf{$m$-dimensional topological pseudomanifold} is a para-compact Hausdorff topological space $X$ which possesses a topological stratification such that $X_{m-1}=X_{m-2}$
	and $X-X_{m-1}$ is dense in X.

\label{Existence2}
	Let $\Sigma$ be a complete fan in $\mathbb{R}^n$ and $\mathcal{
		P}$ its dual polytope. Given any face $\tau \in \mathcal{P}$ there exists an abstract polytope $\mathcal{M}_{\tau}$ satisfying the above conditions $(1)$ and $(2)$ and having a geometrical realization $\vert \mathcal{M}_{\tau} \vert$ as a subpolyhedron of a geometrical realization of $\mathcal{P}$.

The above procedure is one of the cornerstones of this work. Therefore, in this remark, our goal is to provide a schematic elaboration for each step of the construction mentioned above. Consider Figure \ref{T2Modif}. 
\begin{figure}[H]
	\centering
	\includegraphics[width=.26\linewidth]{./T2CW2COMP1.png}
	\includegraphics[width=.14\linewidth]{./T2CW2COMP2.png}
	\includegraphics[width=.20\linewidth]{./T2CW2COMP3.png}
	\includegraphics[width=.20\linewidth]{./T2CW.png}
	\caption{Schematic description of the construction of the map $T^2 \longrightarrow T^2$.}
	\label{T2Modif}
\end{figure}
The left illustration represents a CW structure on $T^2$, where we identify the opposite sides of the large square that contains the green square, the blue square, and the yellow rectangle. Each line represents an $S^1 \in T^2$. The yellow rectangle represents the cylinder $S^1_{v} \times \overline{S^{1}_{h} \setminus L_{h}}$. Under the projection $p_{h}$, the cylinder $S^1_{v} \times \overline{S^{1}_{h} \setminus L_{h}}$ maps to the circle denoted by the black line in the second illustration from the left. The green square in the same illustration represents the cylinder $S^{1}_{h^{\prime}} \times \overline{S^{1}_{v} \setminus L_{v}}$, which maps to the circle denoted by the orange line in the third illustration. In the last step, we map the upper half of the black line, $\widetilde{L}_{v}$, and the right half of the orange line, $\widetilde{L}_{h}$, to the top corner of the blue square, $e^{0}_{0}$.

\label{Hom1Ver}
	Let $\mathcal{X}$ be the link of an isolated point in a compact 8-dimensional toric variety. Then, we have
	\begin{align*}
	\operatorname{rk}(H_{7}(\mathcal{X};\mathbb{Q}) )&=1,\;
	\operatorname{rk}(H_{6}(\mathcal{X};\mathbb{Q}) )=0,\;
	\operatorname{rk}(H_{5}(\mathcal{X};\mathbb{Q}) )=f_{1}-4,\;
	\operatorname{rk(H_{4}(\mathcal{X};\mathbb{Q}) )}=3f_{1}-f_{2}-6-b_{1},\\
	\operatorname{rk}(H_{3}(\mathcal{X};\mathbb{Q}) )&=3f_{1}-f_{2}-6-(b_{1}+b_{2}),\;
	\operatorname{rk}(H_{2}(\mathcal{X};\mathbb{Q}))=f_{1}-4-b_{2},\;
	\operatorname{rk}(H_{1}(\mathcal{X};\mathbb{Q}) )=0,\\
	\operatorname{rk}(H_{0}(\mathcal{X};\mathbb{Q}) )&=1,
	\end{align*}
	where the parameters $b_{1}$ and $b_{2}$ are defined in Equations (\ref{bp1}) and (\ref{bp2}), respectively.

We call a topological space $X$ with filtration
	\begin{align}\label{Qstra}
		X \supset X_{i} \supset  X_{i-1} \supset \dots \supset X_{0} \supset X_{-1}= \emptyset
	\end{align}
	a $\mathbb{Q}$-\textbf{pseudomanifold} if 
	(\ref{Qstra}) can be augmented to a filtration of the form
	\begin{align*}
		X \supset X_{i+k}  \supset \dots \supset X_{i+1} \supset  X_{i} \supset \dots \supset X_{0} \supset X_{-1}= \emptyset,
	\end{align*} 
	such that $X$ is a pseudomanifold with respect to it and the 
	link of each connected component of $X_{i+(j+1)}-X_{i+j}$ for 
	$j=0, \dots, k-1$ in $X$ is a rational homology sphere. 
	We call the filtration (\ref{Qstra}) a 
	\textbf{$\mathbb{Q}$-homology stratification} 
	(or \textbf{$\mathbb{Q}$-stratification} for short) 
	of $X$.

Let $\mathcal{X}$ be the link of an isolated point in an 8-dimensional toric variety. Then, $\mathcal{X}$ is a $\mathbb{Q}$-pseudomanifold with the $\mathbb{Q}$-stratification
	\begin{align}
		\mathcal{X}= \mathcal{X}_{7} \supset \mathcal{X}_{7-6}
	\end{align}

As mentioned in the proof of Corollary \ref{HomSphere}, $\mathcal{X}$ is a pseudomanifold with the following stratification
	 \begin{align*}
	 	\mathcal{X}=\mathcal{X}_{7} \supset \mathcal{X}_{3} \supset \mathcal{X}_{1}.
	 \end{align*}
	 Following the introduced construction of the links in \cite[Section 3]{banagl2024link}, we can show that the link of the top stratum is a homological 3-sphere. Hence, the claim follows.

\label{Cout}
	We call the process of removing a disjoint union of
	cone-like neighborhoods of $\mathcal{X}_{1}$ \textbf{cutting out} the 1-dimensional stratum of $X$.

\label{nseq}
	Let $n$ be a natural number. A CW complex $\mathcal{K}$ is called \textbf{rationally $n$-segmented} if it contains a sub-complex $\mathcal{K}_{<n} \subset \mathcal{K}$ such that
	$
	H_{r}(\mathcal{K}_{<n})=0 \;\; \text{for} \; r \geq n \;
	\text{and} \;
	i_{\ast}:H_{r}(\mathcal{K}_{<n}) \xrightarrow{\;\;\cong\;\;} H_{r}(\mathcal{K}) \; \text{for} \; r <n,
	$
	where $i$ is the inclusion of $\mathcal{K}_{<n}$ into $\mathcal{K}$.

(Goresky-MacPherson.)	
	A \textbf{perversity} 
	\begin{align*}
		\bar{p}: \mathbb{Z}_{ \geq 2} \longrightarrow \mathbb{Z}
	\end{align*}
	is a function such that
	$\bar{p}(2)=0 \; \text{and} \;
	\bar{p}(k+1)- \bar{p}(k) \in \{1,0\}.	$
	The \textbf{complementary perversity} $\bar{q}$ of $\bar{p}$ 
	is the one with $\bar{p}(k)+\bar{q}(k)=k-2$.

\label{IXgen}
	The perversity $\bar{p}$ rational intersection space $I^{\bar{p}}X$ of $X$ is defined to be
	\begin{align*}
		I^{\bar{p}}X=\operatorname{cone}(g)=M \bigcup_{g} \mathcal{C}((X_{n-c})_{i} \times \mathcal{L}_{<k}).
	\end{align*}

\label{IX}
	Let $X \supset X_{n-c} = \sqcup_{i} (X_{n-c})_{i}$ be an $n$-dimensional, compact, oriented, stratified $\mathbb{Q}$-pseudomanifold with one singular stratum $X_{n-c}$ of dimension $(n-c)$ and trivial link bundle. The
	link $\mathcal{L}= \sqcup_{i} \mathcal{L}_{i}$ is assumed to be rationally $(c-1-\bar{p}(c))$ and $(c-1-\bar{q}(c))$-segmented and $X$, $X_{n-c}$ and $\mathcal{L}$ are oriented compatibly.
	Let $I^{\bar{p}}X$ and $I^{\bar{q}}X$ be $\bar{p}$- and $\bar{q}$-intersection spaces of $X$ with $\bar{p}$ and $\bar{q}$ complementary
perversities. Then there exists a generalized Poincaré duality isomorphism
		\begin{align*}
		D: \widetilde{H}_{r}(I^{\bar{p}}X)^{\ast} \xrightarrow{\phantom{-} \cong \phantom{-}} \widetilde{H}_{n-r}(I^{\bar{q}}X),
	\end{align*}
	where
	\begin{align*}
		\widetilde{H}_{r}(I^{\bar{p}}X)^{\ast} = \operatorname{Hom}(\widetilde{H}_{r}(I^{\bar{p}}X),\mathbb{Q}).
	\end{align*}

The link of a point $x_{i} \in \mathcal{X}_{1}$, $\mathcal{L}_{i}$, has the same structure as the link of an isolated singularity in a 6-dimensional toric variety. More specifically, this means the following. The underlying polytope of $\mathcal{L}_{i}$, $\mathcal{M}_{i}$, is a 2-dimensional polytope. We attach a torus $T^3$ to the interior of the polytope $\mathcal{M}_{i}$, and each 1-dimensional face and vertex of $\mathcal{M}_{i}$ is associated with a torus $T^2$ and a circle $S^1$, respectively. Recall that we equipped each $T^{2}$ with the following CW structure:
\begin{align*}
	T^{2} \cong \big( \bigcup_{i=1}^{\alpha-1} e^{2}_{i} \big) \cup \big( \bigcup_{i=1}^{\alpha} e^{1}_{i} \big) \cup e^{0},
\end{align*}
where $\alpha$ is defined in Remark \ref{Alpha}. From each $T^{2}$, we omit one 2-cell. Despite omitting the 2-cells from the tori, the 2-skeleton of the link has not changed. The rest of the proof proceeds along the same lines as in \cite[Proposition 67]{banagl2024link}.

Let $\mathcal{X}$ be the link of an isolated singularity in an 8-dimensional toric variety with the following $\mathbb{Q}$-stratification
	\begin{align*}
	\mathcal{X}=\mathcal{X}_{7} \supset \mathcal{X}_{1}.
	\end{align*}
	Let $\mathcal{L}$ be the link of a connected component of $\mathcal{X}_{1}$ and $f_{1}^{\mathcal{L}}$ be the number of 1-dimensional faces of the underlying polytope of $\mathcal{L}$, $\mathcal{P}$. Then, the Betti numbers of $\mathcal{L}$ are
	\begin{align*}
	b_{5}^{\mathcal{L}}=1,\;		b_{4}^{\mathcal{L}}=0, \;
	b_{3}^{\mathcal{L}}=f_{1}^{\mathcal{L}}-3, \;
	b_{2}^{\mathcal{L}}=f_{1}^{\mathcal{L}}-3, \;
	b_{1}^{\mathcal{L}}=0, \;	
	b_{0}^{\mathcal{L}}&=1.
	\end{align*}

\label{MHOM}
	Let $M$ be the $\mathbb{Q}$-manifold obtained by cutting out all singularities of $\mathcal{X}$, where $\mathcal{X}$ is a link of an isolated singularity in an 8-dimensional toric variety. Then, the lower Betti numbers of $M$ are
	\begin{align*}
	b_{4}^{M}&=3f_{1}-f_{2}-6-(b_{1}+b_{2}), \,
	b_{3}^{M}=3f_{1}-f_{2}-6-b_{1}, \,
	b_{2}^{M}=f_{1}-4, \,
	b_{1}^{M}=0, \,
	b_{0}^{M}=1,
	\end{align*}
	where $f_{1}$and $f_{2}$ are the number of 2-dimensional and 1-dimensional faces, respectively, of $\mathcal{M}$, the underlying 3-dimensional polytope of $\mathcal{X}$. The parameters $b_{2}$ and $b_{1}$ are defined in Equations (\ref{bp1}), and (\ref{bp2}).

The space $M$ is a $\mathbb{Q}$-manifold satisfying Lefschetz duality rationally. Thus, we have
	\begin{align*}
	\text{Hom}(H^{k}(M;\mathbb{Q});\mathbb{Q}) \cong H_{7-k}(M, \partial M ; \mathbb{Q})
	\end{align*}
	From the CW structure of $M$ it is clear that
	\begin{align}\label{MXhomology}
	H_{i}(X) \cong H_{i}( \sfrac{M}{ \partial M } )\; \; \text{for} \;\; i \geq 3
	\end{align}
    because coning off the boundary, $\partial M$, only modifies the lower dimensional cells. Finally, we use $\widetilde{H}_{j}(\sfrac{M}{ \partial M }) \cong \widetilde{H}_{j}(M, \partial M)$.

\label{IntHom}
	Let $\mathcal{X}$ be the link of an isolated singularity in an 8-dimensional toric variety. Let $I^{\bar{n}}\mathcal{X}$ be the generalized intersection space associated with $\mathcal{X}$ with respect to middle perversity $\bar{n}$, as defined in Definition \ref{IXgen}. Then, the Betti numbers of $I^{\bar{n}}\mathcal{X}$ are given by
	\begin{align*}
	b_{7}^{I^{\bar{n}}\mathcal{X}}&=0,\; 
	b_{6}^{I^{\bar{n}}\mathcal{X}}=m-1, \;
	b_{5}^{I^{\bar{n}}\mathcal{X}}=f_{2}-4-b_{2}, \;
	b_{4}^{I^{\bar{n}}\mathcal{X}}=3f_{1}-f_{2}-6-b_{2}, \\
	b_{3}^{I^{\bar{n}}\mathcal{X}}&=3f_{1}-f_{2}-6-b_{2},  \;
	b_{2}^{I^{\bar{n}}\mathcal{X}}=f_{2}-4-b_{2}, \;
	b_{1}^{I^{\bar{n}}\mathcal{X}}=m-1, \;
	b_{0}^{I^{\bar{n}}\mathcal{X}}=1, 
	\end{align*}
	where $f_{1}$ and $f_{2}$ are the numbers of 2-dimensional and 1-dimensional faces of the underlying 3-dimensional polytope of $\mathcal{X}$, $\mathcal{P}$. The parameter $m$ denotes the number of singular components of $\mathcal{X}_{1}$, and we defined $b_{2}$ in Equation (\ref{bp2}).

For the proof, we use the Mayer-Vietoris sequence. Let $M$ be the $\mathbb{Q}$-manifold obtained by cutting out the singularities of $\mathcal{X}$. We set $\mathcal{U} \simeq M$. Let $\mathcal{V} \cong \mathcal{C}(\sqcup_{i} S^{1} \times (\mathcal{L}_{i})_{<k} )$, where $i$ goes over the singular connected components of $\mathcal{X}_{1}$. Hence, we get $\cap := \mathcal{U} \cap \mathcal{V} \simeq \sqcup_{i} S^{1} \times (\mathcal{L}_{i})_{<k}$, and $I^{\bar{n}}\mathcal{X} = \mathcal{U} \cup \mathcal{V}$. Consequently, we have
	\begin{align*}
		&0 \longrightarrow H_{6}(M)  \xrightarrow{\phantom{-} \cong \phantom{-} } H_{6}(I^{\bar{n}}\mathcal{X})  \longrightarrow 0 \\
		&0 \longrightarrow H_{5}(M)  \xrightarrow{\phantom{-} \cong \phantom{-}} H_{5}(I^{ \bar{n} }\mathcal{X})  \longrightarrow 0 \\
		&0 \longrightarrow  H_{1}(I^{ \bar{n} }\mathcal{X}) \xrightarrow{ \phantom{-} \cong \phantom{-}} \overbrace{ \widetilde{H_{0}}(\cap) }^{\cong \mathbb{Q}^{m-1 } } \xrightarrow{\phantom{--}}   0.
	\end{align*}
	Thus, we arrive at $b_{1}^{I \mathcal{X}}=m-1$. Since the singularities of $\mathcal{X}$ are even-co-dimensional, we have $I^{ \bar{n} }\mathcal{X}=I^{ \bar{m} }\mathcal{X}$, and duality yields 
	$b_{6}^{I \mathcal{X}}= m-1$. 
	The more interesting part of the long exact sequence is the following:
	\begin{align*}
		0 &\longrightarrow  \overbrace{H_{4}(M)}^{\cong \mathbb{Q}^{3f_{1}-f_{2}-6-(b_{1}+b_{2})} }  \longrightarrow  H_{4}(I^{ \bar{n} }\mathcal{X})
		\longrightarrow \overbrace{ H_{3}(\cap) }^{\cong \mathbb{Q}^{3f_{1}-f_{2}-6 } } \longrightarrow  \overbrace{H_{3}(M)}^{\cong \mathbb{Q}^{3f_{1}-f_{2}-6-b_{1}} } \\&  \longrightarrow H_{3}(I^{ \bar{n} }\mathcal{X}) \longrightarrow \overbrace{ H_{2}(\cap) }^{\cong \mathbb{Q}^{3f_{1}-f_{2}-6 } } \longrightarrow   \overbrace{H_{2}(M)}^{\cong \mathbb{Q}^{f_{1}-4} }  \longrightarrow H_{2}(I^{ \bar{n} }\mathcal{X}). 
	\end{align*}

	Note that for a non-singular connected component of $S^{1}_{i} \subset \mathcal{X}_{1}$, we have $f_{1}^{i}=3$. Using the well-known Euler formula for 3-dimensional polytopes implies $\sum_{i=1}^{m}(f_{1}^{i}-3)=	\sum_{i=1}^{f_{2}-f_{1}+2}(f_{1}^{i}-3)$. Counting the 1-dimensional faces of the underlying polytope of the link of $S^{1}_{i}$, $\mathcal{P}_{i}$, for each connected component $S^{1}_{i}$ equals counting the neighboring 1-dimensional faces of each vertex in the underlying polytope of $\mathcal{X}$, $\mathcal{M}$. Since each 1-dimensional face of the polytope $\mathcal{M}$ has precisely two vertices in its topological boundary, we have $\sum_{i=1}^{f_{2}-f_{1}+2}f_{1}^{i}=2 f_{2}$. Thus, we get $\sum_{i=1}^{f_{2}-f_{1}+2}(f_{1}^{i}-3)=2f_{2}-3(2-f_{1}+f_{2})=3 f_{1}-f_{2} -6$. Since $\mathcal{L}$ is rationally 3-segmented, we have
	\begin{align*}
		H_{i}(\partial M) \cong H_{i}(S^{1} \times \mathcal{L}_{<3} ) \quad \text{for} \quad i < 3.
	\end{align*}
	The definition yields $H_{i}(M)\cong H_{i}(\mathcal{U})$. Consider the above Mayer-Vietoris exact sequence and the exact sequence of the relative homology of the pair $( M ,\partial M)$ in the following diagram:
	\begin{align}\label{5lemma}
		\xymatrix{
			H_{3}( \partial M)  \ar[r] & H_{3}(M)  \ar[r] & H_{3}(M, \partial M) \ar[r] & H_{2}(M) \ar[r]  & H_{2}(\partial M)\\
			H_{3}(\cap) \ar[r] \ar[u] & H_{3}(M) \ar[r] \ar[u] & H_{3}(I^{ \bar{n} }\mathcal{X}) \ar[u] \ar[r] & H_{2}(M) \ar[u] \ar[r]& H_{2}( \cap). \ar[u] 
		}
	\end{align}
	The commutativity of the diagram
	\begin{align*}
		\xymatrix{ \partial M  \ar@{^{(}->}[r] & M \\
			\cap  \ar@{^{(}->}[u]  \ar@{^{(}->}[ru]   & \\}
	\end{align*}
	ensures that the outer left and right squares in Diagram \ref{5lemma} commute. From \cite[Lemma 2.46]{banagl2010intersection}, it follows that there is a homomorphism $H_{3}(I^{ \bar{n} }\mathcal{X}) \longrightarrow H_{3}(M, \partial M)$ that makes Diagram \ref{5lemma} commutative. Using the 5-lemma yields $b_{3}^{I\mathcal{X}}=b_{3}^{( M ,\partial M)}=b_{4}^{M}$, whereas, in the last equality, we used Lefschetz duality. By using the duality of Betti numbers of intersection spaces and Lemma \ref{MHOM}, we get $b_{4}^{M}=b_{3}^{I\mathcal{X}}=b_{4}^{I\mathcal{X}}=3f_{1}-f_{2}-6-(b_{1}+b_{2})$. Employing the exactness at $H_{3}(\cap) \longrightarrow H_{3}(M)$ and considering that $0 \leq b_{1}$, it immediately follows that $b_{1}=0$, where $b_{1}$ is defined in Equation (\ref{bp1}). Finally, we get $b_{2}^{I\mathcal{X}}=f_{2}-2-b_{2}$.

\label{b2alg}
	Let $\mathcal{X}$ be the link of an isolated singularity in an 8-dimensional toric variety, and let $(M, \partial M)$ be the $\mathbb{Q}$-manifold obtained by cutting out the singularities of $\mathcal{X}$. Let $b_2$ be the parameter defined in Equation (\ref{bp2}), and let $i: \partial M \xhookrightarrow[]{ \;\;\;\; } M$ be the inclusion. Then, we have
	\begin{align*}
		b_{2} = \operatorname{rk}(\operatorname{ker}(H_{3}(\partial M) \xrightarrow{ \; \;  i_{\ast}  \; \; } H_{3} (M)  )).
	\end{align*}

We consider the long exact sequence of the relative homology of $(M, \partial M)$. Using rational Lefschetz duality and Equation (\ref{MXhomology}), we obtain
	\begin{align*}
		0 \longrightarrow \overbrace{H_{4}(M)}^{3 f_{1} - f_{2}-6-b_{2} } \longrightarrow \overbrace{ H_{4}(M, \partial M)  }^{3 f_{1} -f_{2} - 6  } \longrightarrow \overbrace{H_{3} (\partial M) }^{3 f_{1} -f_{2} -6 } \longrightarrow \overbrace{H_{3}(M) }^{3f_{1} -f_{2}-6 }  \longrightarrow \overbrace{H_{3}(M, \partial M)}^{3f_{1} -f_{2}-6- b_{2} }.
	\end{align*}
	By employing the exactness of the above sequence, we arrive at
	$b_{2} = \operatorname{rk}(\operatorname{ker}(H_{3}(\partial M) \longrightarrow H_{3} (M)))$.

\label{MainTheo2}
	Let $\mathcal{X}$ be the link of an isolated singularity in an 8-dimensional toric variety. Let $(M , \partial M)$ be the $\mathbb{Q}$-manifold obtained by cutting out all 1-dimensional singularities of $\mathcal{X}$, and let $i: \partial M \xhookrightarrow[]{ \;\;\;\; } M$ be the inclusion map. Then, the Betti numbers of $\mathcal{X}$ are
	\begin{align*}
		b^{\mathcal{X}}_{7}=1, \;	b^{\mathcal{X}}_{6}=0, \;	&b^{\mathcal{X}}_{5}=f_{1}-4,\;	b^{\mathcal{X}}_{4}=3f_{1}-f_{2}-6, \;
		b^{\mathcal{X}}_{3}=3f_{1}-f_{2}-6-b_{2}, \\	&b^{\mathcal{X}}_{2}=f_{1}-4-b_{2}, \;	b^{\mathcal{X}}_{1}=0, \; b^{\mathcal{X}}_{0}=1,
	\end{align*}
	where 	$b_{2} = \operatorname{rk}(\operatorname{ker}(H_{3}(\partial M) \xrightarrow{ \; \;  i_{\ast}  \; \; } H_{3} (M)  ))$.

In the situation of Definition \ref{DefComp}, we say $\Sigma$ is split by $\Sigma^{\prime}$ and $\Sigma_0$ if there exists a subfan $\hat{\Sigma} \subseteq \Sigma$ such that:
	\begin{itemize}
\item[(a)] $\overline{\phi}_\mathbb{R}$ maps each cone $\hat{\sigma} \in \hat{\Sigma}$ bijectively to a cone $\sigma^{\prime} \in \Sigma^{\prime}$ such that $\overline{\phi}( \hat{ \sigma } \cap N) = \sigma^{\prime} \cap N^{\prime}$. Furthermore, the map $\hat{\sigma} \mapsto \sigma$ defines a bijection $\Sigma^{\prime} \to \hat{\Sigma}$. 

\item[(b)] Given cones $\hat{\sigma} \in \hat{\Sigma}$ and $\sigma_0 \in \Sigma_0$, the sum $\hat{\sigma} + \sigma_0$ lies in $\Sigma$, and every cone of $\Sigma$ arises this way.
	\end{itemize}

\label{HomtGr}
Let $ X_{\Sigma} $ be a toric variety associated with the complete fan $ \Sigma $. Consider the stratification induced by a moment map, and let $ \mathcal{L}_{x} $ be the link of the point $ x \in X_{\Sigma} $. Then, there exists a fiber bundle $ \pi: \mathcal{L}_{x} \longrightarrow X_{\Sigma^{\prime}} $ with fiber $ S^{1} $, where $ X_{\Sigma^{\prime}} $ is a compact toric variety. Furthermore, we obtain the fan $ \Sigma^{\prime} $ as follows:

Let $ \Sigma_{x} \in \Sigma $ be the corresponding cone to the orbit in which $ x $ lies. The complete fan $ \Sigma^{\prime} $ is obtained by projecting the topological boundary of $ \Sigma_{x} \subset N := \operatorname{span}(\Sigma_{x}) \cap \mathbb{Z}^{\dim(\Sigma) } \cong \mathbb{Z}^{\dim ( \Sigma_{x} )  }  $ along a 1-dimensional cone $ \tau $ lying in the interior of $ \Sigma_{x} $ into the lattice $N_{0}^{\perp} := \operatorname{span} (\tau^{\perp}) \cap \mathbb{Z}^{\dim ( \Sigma )} \cong \mathbb{Z}^{\dim (\Sigma_{x})-1} $.

First, we prove the statement for a point in the bottom stratum of $X_{\Sigma}$. We use the same notation as in the above discussion. Using the short exact sequence \ref{LongEx} and \cite[Theorem 3.3.19]{cox2024toric}, we conclude that $X_{\mathring{\Sigma}_{\nu}}$ is a fiber bundle over $X_{\Sigma^{\prime}_{\nu} }$ with fiber $X_{\Sigma_{0}}$, where $\mathring{\Sigma}_{\nu} \subseteq N$, $\Sigma^{\prime}_{\nu} \subset N^{\prime}$, and $\Sigma_{0}\subseteq N_{0}$.
Thus, we arrive at the following fiber bundle:
\begin{align}
	\mathbb{R} \times S^{1} \xrightarrow{g=(\operatorname{id}_{\mathbb{R}},\overline{g})} \mathbb{R} \times \mathcal{L}_{\nu} \xrightarrow{f=(\operatorname{pr},\overline{f})} \ast \times X_{\Sigma^{\prime}_{\nu} },
\end{align}
where the maps $\operatorname{id}_{\mathbb{R}}$ and $\operatorname{pr}$ denote the identity map and the projection to a point, respectively. It follows that 
\begin{align}
 S^{1} \xrightarrow{\overline{g}} \mathcal{L}_{\nu} \xrightarrow{\overline{f}}   X_{\Sigma^{\prime}_{\nu} }
\end{align}
is also a fiber bundle. This completes the proof for the case where $ x $ lies in the bottom stratum of $ X_{\Sigma} $. For an arbitrary point $ x $, let $ \Sigma_{x} \in \Sigma $ be the corresponding cone to the orbit in which $ x $ lies. Consider $ \Sigma_{x} $ as a cone in the sublattice $ N := \operatorname{span}(\Sigma_{x}) \cap \mathbb{Z}^{\dim(\Sigma) } \cong \mathbb{Z}^{\dim ( \Sigma_{x} )  } $. Hence, we arrive at $X_{\Sigma_{x} } \cong \mathring{\mathcal{C}} (\mathcal{L}_{x})$, where $\Sigma_{x} \subset N$. Let $\mathring{\Sigma}_{x} \subset N$ be the fan obtained from $\Sigma_{x}$ by removing its interior. It follows that $X_{\mathring{\Sigma}_{x}} \cong \mathcal{L}_{x} \times \mathbb{R}$. The fan $\mathring{\Sigma}_{x}$ splits by $\Sigma_{0} = \{ 0\}$ and $\Sigma^{\prime}_{x} := \pi^{\prime} (\mathring{\Sigma}_{x})$. The map $\pi^{\prime} : N \longrightarrow  ( \sfrac{N_{\mathbb{R}}}{ (N_{0})_{\mathbb{R}} } ) \cap N $ is defined where $N_0 \subset N$ is the lattice spanned by a 1-dimensional cone lying in the interior of $\Sigma_{x}$. The rest of the proof follows the same lines as in the case of the points in the bottom stratum.

Let $\mathcal{L}_{x}$ be the link of an isolated point in a toric variety of real dimension 8. Let $\pi: \mathcal{L}_{x} \longrightarrow X_{\Sigma}$ be an $S^{1}$-bundle, as in Theorem \ref{HomtGr}. Let $\Omega \in H^{2}(X_{\Sigma})$ denote the characteristic cohomology class of this $S^{1}$-bundle, as defined in \cite[Theorem 3.3]{chern1950homology}. Then, the non-combinatorial invariant parameter $b$ in the Betti numbers of $X_{\Sigma}$, defined in \cite{mcconnell1989rational} or \cite{banagl2024link}, is given by
		\begin{align*}
			b=\operatorname{rk}\big(\operatorname{ker}(\Psi^{\prime}:H_{4}(X_{\Sigma}) \longrightarrow H_{2}(X_{\Sigma}))\big),
		\end{align*}
		where $\Psi^{\prime}(z)= \Omega \cap z$ for all $z \in H_{4}(X_{\Sigma})$.

The homomorphisms $\Psi^{\prime}:H_{p}(B) \longrightarrow H_{p-d-1}(B)$ associated to an $S^{d}$-bundle have been studied in \cite{chern1950homology}. For the $S^{1}$-bundle $\pi:\mathcal{L}_{x} \longrightarrow X_{\Sigma}$, the claim follows from the exactness of sequence
	\begin{align*}
		0 \rightarrow H_{3}(X_{\Sigma}) \rightarrow H_{4}(\mathcal{L}_{x}) \rightarrow H_{4}(X_{\Sigma}) 
		\rightarrow H_{2}(X_{\Sigma}) \rightarrow H_{3}(\mathcal{L}_{x}) \rightarrow H_{3}(X_{\Sigma}) \rightarrow 0.
	\end{align*} 
	More precisely, one obtains $\operatorname{rk}\big(\operatorname{ker}(H_{4}(X_{\Sigma}) \longrightarrow H_{2}(X_{\Sigma}))\big)=b_{4}^{\mathcal{L}_{x}}-b_{3}^{X_{\Sigma}}$. On the other hand, $b_{4}^{\mathcal{L}_{x} }=3 f_{1}^{\mathcal{L}_{x} }-f_{2}^{\mathcal{L}_{x}}-6$ and $b_{3}^{X_{\Sigma} }=3 f_{1}^{X_{\Sigma} }-f_{2}^{X_{\Sigma}}-6-b$. The numbers $f_{1}$ and $f_{2}$ denote the number of 2-dimensional and 1-dimensional faces of the underlying polytopes of the corresponding space. As noted in the proof of Theorem \ref{BettiComp}, $f_{1}^{\mathcal{L}_{x} }=f_{1}^{X_{\Sigma} }$ and $f_{2}^{\mathcal{L}_{x} }=f_{2}^{X_{\Sigma} }$. The claim then follows.
